import{_ as a,o as e,c as s,a2 as n}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"环境与配置管理","description":"用多环境隔离、配置与代码分离、密钥独立和容器化，让\\"在我机器上能跑\\"不再是上线理由。","frontmatter":{"title":"环境与配置管理","description":"用多环境隔离、配置与代码分离、密钥独立和容器化，让\\"在我机器上能跑\\"不再是上线理由。"},"headers":[],"relativePath":"engineering/environment.md","filePath":"engineering/environment.md","lastUpdated":1786271684000}'),p={name:"engineering/environment.md"};function d(l,t,i,o,r,c){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="环境与配置管理" tabindex="-1">环境与配置管理 <a class="header-anchor" href="#环境与配置管理" aria-label="Permalink to &quot;环境与配置管理&quot;">​</a></h1><p>&quot;在我本地是好的&quot;是工程史上最经典的借口。它之所以反复出现，根源是环境不一致：开发用一套依赖、测试用一套、生产又是另一套，配置散落各处，密钥混进代码仓库。环境与配置管理的目标就一句话——让同一段代码在不同环境里行为可预期、可复现，且密钥绝不外泄。这件事不做扎实，所有的 CI、测试、回滚都建立在流沙上。</p><h2 id="多环境-dev-staging-prod" tabindex="-1">多环境：dev / staging / prod <a class="header-anchor" href="#多环境-dev-staging-prod" aria-label="Permalink to &quot;多环境：dev / staging / prod&quot;">​</a></h2><p>不同环境承担不同职责，不要混用：</p><table tabindex="0"><thead><tr><th>环境</th><th>作用</th><th>数据</th><th>稳定性要求</th></tr></thead><tbody><tr><td>dev</td><td>本地开发、调试</td><td>mock 或脱敏样本</td><td>不要求，常崩无妨</td></tr><tr><td>staging</td><td>上线前验证、集成测试</td><td>类生产的脱敏数据</td><td>尽量稳定，接近生产</td></tr><tr><td>prod</td><td>真实用户</td><td>真实数据</td><td>最高，变更受控</td></tr></tbody></table><p>关键原则：<strong>staging 要尽可能像 prod</strong>——同样的镜像、同样的配置结构、同样的依赖版本，只是值不同。staging 和 prod 差异越大，staging 的验证价值越低，上线就是在赌。</p><blockquote><p>常见反模式：staging 连的是测试库的旧数据、跑的是不同的依赖版本、甚至没有和 prod 一样的中间件。这种 staging 过不了的东西，上线照样崩。</p></blockquote><h2 id="配置与代码分离" tabindex="-1">配置与代码分离 <a class="header-anchor" href="#配置与代码分离" aria-label="Permalink to &quot;配置与代码分离&quot;">​</a></h2><p>配置（数据库地址、第三方 key、功能开关、阈值）不应该写死在代码里。Twelve-Factor App 的核心一条：<strong>配置通过环境变量注入，代码保持环境无关</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>错误：</span></span>
<span class="line"><span>  const dbUrl = &quot;mysql://prod-user:pwd@10.0.0.5/orders&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>正确：</span></span>
<span class="line"><span>  const dbUrl = process.env.DB_URL</span></span></code></pre></div><p>这样同一个镜像可以跑在所有环境，只是注入的 <code>.env</code> 不同。发布物和环境解耦，是可重复部署的基础。</p><table tabindex="0"><thead><tr><th>配置类型</th><th>存放位置</th></tr></thead><tbody><tr><td>业务参数、阈值、开关</td><td>配置中心 / 环境变量</td></tr><tr><td>数据库、缓存地址</td><td>环境变量</td></tr><tr><td>API 密钥、证书</td><td>密钥管理服务（见下）</td></tr><tr><td>框架默认值、不环境相关的常量</td><td>代码里没关系</td></tr></tbody></table><h2 id="密钥管理-绝不能进代码仓库" tabindex="-1">密钥管理：绝不能进代码仓库 <a class="header-anchor" href="#密钥管理-绝不能进代码仓库" aria-label="Permalink to &quot;密钥管理：绝不能进代码仓库&quot;">​</a></h2><p>把密钥提交到 git 是工程上的大忌，而且一旦提交，&quot;删除&quot;也无济于事——历史里永远在。正确做法：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>密钥的生命周期：</span></span>
<span class="line"><span>  生成 → 存进密钥服务（KMS / Vault / 云厂商 Secret Manager）</span></span>
<span class="line"><span>       → 运行时按需拉取或注入环境变量</span></span>
<span class="line"><span>       → 轮换（定期更换）</span></span>
<span class="line"><span>       → 吊销（泄露时立即失效）</span></span></code></pre></div><p>务实的底线：</p><ul><li>仓库里加 <code>.env.example</code> 只放占位符，真值永不提交。</li><li>CI/CD 从密钥服务注入，不在脚本里硬编码。</li><li>定期轮换密钥，泄露时能快速吊销而不是全员改密码。</li></ul><h2 id="feature-flag-把发布和解耦分开" tabindex="-1">Feature Flag：把发布和解耦分开 <a class="header-anchor" href="#feature-flag-把发布和解耦分开" aria-label="Permalink to &quot;Feature Flag：把发布和解耦分开&quot;">​</a></h2><p>传统发布是&quot;上线即生效&quot;，风险集中在一刻。Feature Flag（功能开关）把&quot;代码部署&quot;和&quot;功能开启&quot;拆开：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>代码合并 → 部署到生产（功能默认关闭）</span></span>
<span class="line"><span>        → 小比例打开开关灰度</span></span>
<span class="line"><span>        → 观察，有问题一键关闭，无需回滚代码</span></span>
<span class="line"><span>        → 全量放开</span></span></code></pre></div><table tabindex="0"><thead><tr><th>场景</th><th>Flag 价值</th></tr></thead><tbody><tr><td>高风险新功能</td><td>灰度发布，出问题秒级关闭</td></tr><tr><td>A/B 测试</td><td>不同用户走不同逻辑</td></tr><tr><td>紧急止血</td><td>不重新部署就能关掉出问题的功能</td></tr><tr><td>未完成功能</td><td>主干开发，功能未完成也能合并</td></tr></tbody></table><blockquote><p>Flag 不是越多越好。每个 flag 都是技术债——长期不清理的 flag 让代码充满死分支。上线稳定后要及时清理过期 flag。</p></blockquote><h2 id="环境一致性-容器化" tabindex="-1">环境一致性：容器化 <a class="header-anchor" href="#环境一致性-容器化" aria-label="Permalink to &quot;环境一致性：容器化&quot;">​</a></h2><p>保证环境一致最有效的手段是容器化（Docker）。镜像把操作系统、依赖、运行时打包在一起，&quot;在我机器上能跑&quot;变成&quot;在哪里都能跑&quot;。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>开发：docker-compose up 起一套本地依赖</span></span>
<span class="line"><span>CI：用同一个 Dockerfile 构建镜像跑测试</span></span>
<span class="line"><span>生产：部署同一个镜像</span></span></code></pre></div><p>要点：<strong>dev / staging / prod 用同一个镜像</strong>，差异只在配置。不要每个环境自己拼一套 Dockerfile，那样又回到不一致的老路。</p><h2 id="常见错误-配置漂移" tabindex="-1">常见错误：配置漂移 <a class="header-anchor" href="#常见错误-配置漂移" aria-label="Permalink to &quot;常见错误：配置漂移&quot;">​</a></h2><p>环境管理最隐蔽的问题是&quot;配置漂移&quot;——时间久了，各环境手工改过一些东西，没人记得改了什么，prod 成了一个谁也不敢动的黑箱。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>症状：</span></span>
<span class="line"><span>  - &quot;这个服务器的某个参数当年谁手动调过，别动&quot;</span></span>
<span class="line"><span>  - 重建一台机器，跑起来行为不一样</span></span>
<span class="line"><span>  - 灾难恢复时发现没人能从零搭出当前的生产环境</span></span></code></pre></div><p><strong>正确做法</strong>：所有环境变更必须走代码（基础设施即代码，IaC）。手动 SSH 上去改的东西不进版本控制，就是漂移的源头。无论是 Nginx 配置、防火墙规则还是环境变量，都要能从一份声明文件 + 一条命令完整重建。</p><h2 id="务实的检查清单" tabindex="-1">务实的检查清单 <a class="header-anchor" href="#务实的检查清单" aria-label="Permalink to &quot;务实的检查清单&quot;">​</a></h2><ul><li>dev / staging / prod 是否用同一个镜像或构建产物，只差配置？</li><li>所有配置是否都从环境变量或配置中心读取，没有硬编码？</li><li>密钥是否从未进过 git 仓库，是否定期轮换？</li><li>是否用 Feature Flag 把高风险发布改成灰度？</li><li>环境能否从一份 IaC 声明完整重建，还是依赖某人的记忆？</li><li>是否禁止手工 SSH 改配置，所有变更走代码评审？</li></ul>`,32)])])}const u=a(p,[["render",d]]);export{g as __pageData,u as default};
